/** Formats a probability as a percentage string. */
export function pct(p: number | null | undefined, digits = 0): string {
  if (p === null || p === undefined || !Number.isFinite(p)) return '–';
  return `${(p * 100).toFixed(digits)}%`;
}

/** Signed percentage-point change, e.g. "+2.5 pts". */
export function pts(delta: number, digits = 1): string {
  const v = delta * 100;
  return `${v > 0 ? '+' : v < 0 ? '−' : '±'}${Math.abs(v).toFixed(digits)} pts`;
}

/** Short relative time, e.g. "5 min ago". */
export function relativeTime(iso: string, now: Date = new Date()): string {
  const diff = Math.round((now.getTime() - Date.parse(iso)) / 1000);
  if (!Number.isFinite(diff)) return '–';
  if (diff < 60) return 'just now';
  if (diff < 3600) return `${Math.floor(diff / 60)} min ago`;
  if (diff < 86400) return `${Math.floor(diff / 3600)} h ago`;
  return `${Math.floor(diff / 86400)} d ago`;
}

export function shortDate(tSec: number): string {
  return new Date(tSec * 1000).toLocaleDateString('en-US', { month: 'short', day: 'numeric', timeZone: 'UTC' });
}

